import {mountApplicationShell} from '../forge-shell/shell.mjs';
import {deploymentPath} from '../deployment.mjs';
export function mountForgeShell({doc,root,onMode,getCircuit,getProject,bridge,onLocalSave}={}){
 const $=s=>doc.querySelector(s),make=(tag,text)=>{const n=doc.createElement(tag);if(text)n.textContent=text;return n;};
 const oldBrowser=$('.forge-controls'),props=$('.forge-inspector'),form=$('#forge-controls'),bench=$('.forge-workbench'),physical=$('#forge-mode-physical'),signal=$('#forge-response-lab'),workflow=$('#forge-workflow'),parts=$('#forge-logical-parts'),local=$('.local-projects');
 const help=make('div');help.append($('.forge-heading'),workflow);for(const n of [...root.querySelectorAll('.category-learning,.forge-back')])help.append(n);const learning=[...root.children].find(n=>n.tagName==='DETAILS');if(learning)help.append(learning);
 const propertyTitle=make('h2','Properties'),design=make('div');design.className='forge-properties-controls';design.append($('#forge-circuit-state'),form);props.prepend(propertyTitle,design);for(const n of [...oldBrowser.children]){help.append(n);}oldBrowser.remove();
 const status=make('div');status.append($('#forge-status'),$('#forge-workbench-identity'));const importNotice=$('#forge-import-note');if(importNotice)status.append(importNotice);const availability=$('#forge-capability-status'),limits=$('#forge-instrument-limit');if(availability)status.append(availability);if(limits)status.append(limits);const source=$('.forge-source-context');if(source)help.append(source);const contextMenu=$('.forge-context-actions');if(contextMenu)help.append(contextMenu);
 help.append($('.forge-workbench-heading'));
 const diagrams=$('.forge-workspace-modes');const modeButtons=[...diagrams.querySelectorAll('button')];diagrams.hidden=true;help.append(diagrams);
 const commands=[{id:'configure',group:'Design',title:'Guitar & Pickups',run:()=>{showGroup('guitar');shell.openPanel('properties');}},{id:'circuit',group:'Design',node:modeButtons.find(n=>n.dataset.forgeMode==='physical')},{id:'signal',group:'Analyse',node:modeButtons.find(n=>n.dataset.forgeMode==='signal')},{id:'local',group:'Design',title:'Save locally / share circuit',view:'local'},{id:'undo',group:'Design',node:$('#forge-undo')},{id:'redo',group:'Design',node:$('#forge-redo')},{id:'parts',group:'Build',title:'Parts / BOM',view:'build'},...['forge-view-wiring','forge-guided-build','forge-kit','forge-design-bleed'].map(id=>({id,group:'Build',node:$('#'+id)})),{id:'export',group:'Document',title:'Wiring SVG / Print',run:()=>{const a=$('#forge-view-wiring');if(a.hidden){shell.selectView('build',{focus:true});return;}a.click();}}];
 if(bridge?.send)commands.push({id:'cloud-revision',group:'Design',node:bridge.send});
 const browser=[...['guitar','controls','selector','switching','values','wiring','advanced'].map(id=>({id,title:{guitar:'Guitar & Pickups',controls:'Controls',selector:'Selector',switching:'Switching',values:'Values',wiring:'Wiring',advanced:'Advanced'}[id],view:'circuit',properties:true,run:()=>showGroup(id)})),{id:'circuit',title:'Circuit',view:'circuit',run:()=>showInspection(null)},{id:'signal',title:'Signal / Response',view:'signal',run:()=>showInspection(null)},{id:'components',title:'Components',view:'circuit',properties:true,run:()=>{showInspection(null);$('.forge-inventory').open=true;}},{id:'parts',title:'Build / Parts',view:'build'},{id:'local',title:'Local saves / Share',view:'local'}];
 function showGroup(id){propertyTitle.textContent=browser.find(x=>x.id===id)?.title||'Properties';design.hidden=false;for(const n of [...props.children])if(n!==design&&n!==propertyTitle)n.hidden=true;for(const g of form.querySelectorAll('[data-configure-group]')){g.hidden=g.dataset.configureGroup!==id;g.open=!g.hidden;}shell?.setSelection({kind:'configuration',id});}
 function showInspection(selection){propertyTitle.textContent='Properties / Inspector';design.hidden=true;for(const n of [...props.children])if(n!==design)n.hidden=false;shell?.setSelection(selection);}
 let shell;const context=bridge?.context;shell=mountApplicationShell(root,{id:'forge-design',context:{kind:context?'project':'local',title:context?.title||'Local design',revision:context?.revision||'',save:context?'Editor design · cloud save is explicit':'Unsaved local design'},views:[{id:'circuit',title:'Circuit',node:physical},{id:'signal',title:'Signal',node:signal},{id:'build',title:'Build / Parts',node:parts},{id:'local',title:'Local Save / Share',node:local}],commands,browser,properties:props,status,help,links:[{text:'Projects',href:deploymentPath('/circuit-forge/projects/')},{text:'Account',href:deploymentPath('/account/')}],drawers:{browser:$('#forge-configure-sheet'),properties:$('#forge-inspector-sheet')},onView:id=>{if(id==='circuit')onMode('physical',true);if(id==='signal')onMode('signal',true);}});
 shell.browser.classList.add('forge-controls');shell.workspace.classList.add('forge-workbench');help.append(...bench.children);bench.remove();$('.forge-mobile-toolbar')?.setAttribute('hidden','');showInspection(null);
 // Move, rather than duplicate, the local Save control into the persistent application bar.
 const localDetails=local.querySelector('details');localDetails.open=true;const save=[...local.querySelectorAll('button')].find(n=>n.textContent==='Save current');if(save){save.textContent='Save locally';shell.appbar.append(save);save.addEventListener('click',()=>queueMicrotask(()=>{const message=local.querySelector('[role="status"]')?.textContent;if(message==='Project saved on this browser.'){saved=JSON.stringify(getCircuit().state);shell.setContext({save:'Saved locally on this browser'});onLocalSave?.();}}));}
 if(bridge?.send){shell.appbar.append(bridge.send);bridge.send.textContent=context?'Send for cloud revision':'Send design to Projects';}
 let saved=null;
 return Object.assign(shell,{showInspection(selection,{open=false}={}){showInspection(selection);if(open)shell.openPanel('properties');},update(){if(!context){const title=getProject()?.name||'Local design';shell.setContext({title,save:saved&&saved===JSON.stringify(getCircuit().state)?'Saved locally on this browser':'Unsaved local design'});}else shell.setContext({save:'Editor design · send for explicit cloud revision'});},modeChanged(mode){shell.selectView(mode==='signal'?'signal':'circuit');}});
}
